<?php require '../includes/auth.php';require '../includes/header.php';$u=guard('employee');
$s=db()->prepare("SELECT a.*,c.name cat FROM employee_assessments a JOIN evaluation_categories c ON c.id=a.category_id WHERE a.employee_id=? AND a.is_published=1 ORDER BY a.eval_date DESC");$s->execute([$u['id']]);$rows=$s->fetchAll();page_head('My Evaluations',[],$u);?>
<div class="card table-responsive"><table class="table mb-0"><tr><th>Date</th><th>Category</th><th>Batch</th><th>Score</th><th>Rating</th><th>Remarks</th></tr><?php foreach($rows as $r){$rt=rating_for($r['score_percent']);?><tr><td><?=e($r['eval_date'])?></td><td><?=e($r['cat'])?></td><td><?=e($r['batch_title'])?></td><td><?=e($r['score_percent'])?>%</td><td><span class="badge text-bg-<?=e($rt['color'])?>"><?=e($rt['label'])?></span></td><td><?=e($r['remarks'])?></td></tr><?php }if(!$rows)echo'<tr><td colspan=6 class="text-center text-muted p-4">No published results yet</td></tr>';?></table></div><?php page_foot();
